// rich-card-meanings.mjs
// 78장 웨이트-스미스 타로의 전문 리더 수준 해석 데이터.
// 기존 buildMeaning() 템플릿 위에 카드별 오버라이드로 얹혀, 정/역방향과
// 질문 유형(연애/관계/재회/상대속마음/현재심리/미래/진로/금전/일상)별로
// 카드 고유의 상징과 반전 논리를 반영한 문장을 제공한다.
//
// 데이터는 카드당 upright/reversed 각각 12개 핵심 필드를 "압축 정의"로 담고,
// expandRichMeaning()이 이를 ensureMeaningShape 호환 오버라이드로 확장한다.
// (compact 필드가 없으면 core/advice 등에서 자연스럽게 파생한다.)

function normalize(value) {
  if (Array.isArray(value)) return value.map((v) => String(v || "").trim()).filter(Boolean);
  const text = String(value == null ? "" : value).trim();
  return text ? [text] : [];
}

function firstOf(...candidates) {
  for (const c of candidates) {
    const arr = normalize(c);
    if (arr.length) return arr[0];
  }
  return "";
}

// 압축 정의(o) → ensureMeaningShape 호환 오버라이드로 확장
function expandOrientation(o, keywords) {
  const core = firstOf(o.core);
  const advice = firstOf(o.advice, core);
  const caution = firstOf(o.caution);
  const general = firstOf(o.general, core);
  return {
    keywords: normalize(keywords).slice(0, 6),
    coreMeaning: core,
    core: normalize(o.scene ? [o.scene, core] : core),
    light: normalize(o.light || core),
    shadow: normalize(o.shadow || caution),
    general: normalize(general),
    love: normalize(o.love),
    relationship: normalize(o.relationship || o.love),
    reunion: normalize(o.reunion),
    exMind: normalize(o.exMind),
    currentMind: normalize(o.currentMind),
    future: normalize(o.future),
    career: normalize(o.career),
    money: normalize(o.money),
    moneyWork: normalize(o.moneyWork || o.money || o.career),
    healthMind: normalize(o.healthMind),
    daily: normalize(o.daily),
    monthly: normalize(o.monthly || general),
    advice: normalize(advice),
    adviceText: advice,
    caution: normalize(caution),
    shadowText: caution,
    shadowNote: caution,
    psychologicalMeaning: firstOf(o.psychologicalMeaning, o.currentMind, core),
    selfEsteemMeaning: firstOf(o.selfEsteemMeaning, general, core),
  };
}

function expandRichMeaning(def) {
  return {
    upright: expandOrientation(def.upright || {}, def.keywords),
    reversed: expandOrientation(def.reversed || {}, def.reversedKeywords || def.keywords),
  };
}

