// 경고 카드(악마·탑·달·소드10·펜타클5)는 warning-card-guard.mjs가 페일세이프
// 정책과 함께 리치 문구를 단독으로 소유한다. 여기 MAJOR에 남은 M15/M16/M18
// 정의는 참조용이며, 아래 루프에서 제외되어 실제 카드 데이터에는 반영되지 않는다.
const WARNING_OWNED_CODES = new Set(["M15", "M16", "M18", "S10", "P05"]);

const RICH_CARD_OVERRIDES = {};
for (const [code, def] of Object.entries({ ...MAJOR, ...MINOR })) {
  if (WARNING_OWNED_CODES.has(code)) continue;
  RICH_CARD_OVERRIDES[code] = expandRichMeaning(def);
}

export { RICH_CARD_OVERRIDES, expandRichMeaning };
